def can_equal_partition_grid(grid):
    total=sum(map(sum,grid));running=0
    for row in grid[:-1]:
        running+=sum(row)
        if running*2==total:return True
    running=0
    for column in range(len(grid[0])-1):
        running+=sum(row[column] for row in grid)
        if running*2==total:return True
    return False

